"""Repair reflection lifetimes in C generated by TeaVM 0.16.0."""

import argparse
import re
from pathlib import Path


CLASS_INITIALIZER = re.compile(
    r"^void (?P<name>sysinitclass_\w+)\(\) \{\n(?P<body>.*?)^\}$",
    re.MULTILINE | re.DOTALL,
)
REFLECTION_ASSIGNMENT = re.compile(
    r"^(?P<target>(?P<indent>[ \t]*)vt_\d+->reflection) = &\(TeaVM_ClassReflection\) "
    r"(?P<descriptor>\{\n.*?^(?P=indent)\});$",
    re.MULTILINE | re.DOTALL,
)
DESCRIPTOR_MARKER = b"->reflection = &(TeaVM_ClassReflection)"
CONSTRUCTOR_FUNCTION = re.compile(
    r"^void\* meth_jlr_Constructor_newInstance\(void\* teavm_this_, "
    r"TeaVM_Array\* teavm_local_1\) \{\n(?P<body>.*?)^\}$",
    re.MULTILINE | re.DOTALL,
)
CONSTRUCTOR_STACK = re.compile(r"^    TEAVM_ALLOC_STACK\(INT32_C\((?P<count>\d+)\)\);$", re.MULTILINE)
CONSTRUCTOR_CALL = re.compile(
    r"^(?P<indent>[ \t]+)teavm_reflection_callMethod\("
    r"(?:TEAVM_FIELD\(teavm_this_, cls_jlr_Executable, fld_methodInfo\)|teavm_local_\d+), "
    r"(?P<instance>teavm_local_\d+), (?P<args>teavm_local_\d+)\);$",
    re.MULTILINE,
)
CONSTRUCTOR_ROOT_MARKER = "    /* Keep the reflection intrinsic arguments alive across GC. */"


def fix_constructor_roots(generated):
    path = generated / "c" / "j" / "l" / "r" / "Constructor.c"
    if not path.is_file():
        return False
    source = path.read_text(encoding="utf-8")
    match = CONSTRUCTOR_FUNCTION.search(source)
    if match is None:
        if "meth_jlr_Constructor_newInstance(" in source:
            raise ValueError(f"Unrecognized TeaVM constructor signature in {path}")
        return False
    body = match["body"]
    if CONSTRUCTOR_ROOT_MARKER in body:
        return False
    stacks = list(CONSTRUCTOR_STACK.finditer(body))
    calls = list(CONSTRUCTOR_CALL.finditer(body))
    if len(stacks) != 1 or len(calls) != 1:
        raise ValueError(f"Unrecognized TeaVM reflective constructor in {path}")
    stack, = stacks
    call, = calls
    this_slot = int(stack["count"])
    arguments_slot, instance_slot = this_slot + 1, this_slot + 2
    # The intrinsic call is not treated as a safepoint by the emitter.
    # Keep the receiver and arguments across earlier allocations, and pin
    # the instance across the call so the C local remains valid after GC.
    indent = call["indent"]
    body = body.replace(
        stack[0],
        f"    TEAVM_ALLOC_STACK(INT32_C({instance_slot + 1}));\n"
        f"{CONSTRUCTOR_ROOT_MARKER}\n"
        f"    TEAVM_GC_ROOT(INT32_C({this_slot}), teavm_this_);\n"
        f"    TEAVM_GC_ROOT(INT32_C({arguments_slot}), teavm_local_1);\n"
        f"    TEAVM_GC_ROOT_RELEASE(INT32_C({instance_slot}));",
    ).replace(
        call[0],
        f"{indent}TEAVM_GC_ROOT(INT32_C({arguments_slot}), {call['args']});\n"
        f"{indent}TEAVM_GC_ROOT(INT32_C({instance_slot}), {call['instance']});\n"
        + call[0],
    )
    path.write_text(source[:match.start("body")] + body + source[match.end("body"):],
                    encoding="utf-8", newline="\n")
    return True


def rewrite_class_initializer(match):
    body = match["body"]
    assignment = REFLECTION_ASSIGNMENT.search(body)
    if assignment is None:
        return match[0]

    # A block-scope compound literal and its nested class lists expire when
    # sysinitclass returns. At file scope, both have static storage duration.
    name = match["name"] + "_reflection"
    declaration = f"static TeaVM_ClassReflection {name} = {assignment['descriptor']};\n"
    body = body[:assignment.start()] + f"{assignment['target']} = &{name};" + body[assignment.end():]
    return declaration + f"void {match['name']}() {{\n{body}}}"


def fix_reflection_lifetime(generated):
    if not (generated / "all.c").is_file():
        raise ValueError(f"No generated TeaVM C program in {generated}")
    count = 0
    for path in (generated / "c").rglob("*.c"):
        raw = path.read_bytes()
        if DESCRIPTOR_MARKER not in raw:
            continue
        source = raw.decode("utf-8").replace("\r\n", "\n")
        updated = CLASS_INITIALIZER.sub(rewrite_class_initializer, source)
        if DESCRIPTOR_MARKER.decode() in updated:
            raise ValueError(f"Unrecognized TeaVM reflection initializer in {path}")
        count += raw.count(DESCRIPTOR_MARKER)
        path.write_text(updated, encoding="utf-8", newline="\n")
    return count


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("generated", type=Path)
    args = parser.parse_args()
    print(f"Updated {fix_reflection_lifetime(args.generated)} reflection initializers")
    if fix_constructor_roots(args.generated):
        print("Rooted the reflective constructor across allocations")
